#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    bool canCross(int m, int n, int day, vector<vector<int>>& cells) {
        vector<vector<int>> grid(m, vector<int>(n, 0));
        for (int i = 0; i < day; ++i)
            grid[cells[i][0] - 1][cells[i][1] - 1] = 1;

        queue<pair<int, int>> q;
        for (int j = 0; j < n; ++j)
            if (grid[0][j] == 0) q.emplace(0, j), grid[0][j] = 1;

        vector<pair<int, int>> dirs = {{0,1},{1,0},{0,-1},{-1,0}};
        while (!q.empty()) {
            auto [x, y] = q.front(); q.pop();
            if (x == m - 1) return true;
            for (auto [dx, dy] : dirs) {
                int nx = x + dx, ny = y + dy;
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 0) {
                    grid[nx][ny] = 1;
                    q.emplace(nx, ny);
                }
            }
        }
        return false;
    }

    int latestDayToCross(int m, int n, vector<vector<int>>& cells) {
        int lo = 1, hi = m * n, res = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (canCross(m, n, mid, cells)) {
                res = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return res;
    }
};
